import{_ as r,a as o,b as s,c as n}from"./chunks/blend-modes.AsLE9LMZ.js";import{_ as i,o as l,c as e,a2 as a}from"./chunks/framework.Bzj1XTnB.js";const y=JSON.parse('{"title":"लेयर","description":"बैकग्राउंड, कैरेक्टर और इफ़ेक्ट अलग रखें, और opacity, ब्लेंडिंग, क्लिपिंग मास्क व ग्लो इस्तेमाल करें।","frontmatter":{"lang":"hi","slug":"layers","order":6,"title":"लेयर","description":"बैकग्राउंड, कैरेक्टर और इफ़ेक्ट अलग रखें, और opacity, ब्लेंडिंग, क्लिपिंग मास्क व ग्लो इस्तेमाल करें।"},"headers":[],"relativePath":"hi/layers.md","filePath":"hi/layers.md"}'),g={name:"hi/layers.md"};function p(c,t,_,d,m,u){return l(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="लेयर" tabindex="-1">लेयर <a class="header-anchor" href="#लेयर" aria-label="Permalink to &quot;लेयर&quot;">​</a></h1><p>लेयर एक-दूसरे के ऊपर रखी पारदर्शी शीट जैसी हैं। एक पर बैकग्राउंड, दूसरी पर कैरेक्टर रखें — फिर बैकग्राउंड को छुए बिना कैरेक्टर दोबारा बना सकते हैं। एक प्रोजेक्ट में <strong>15 लेयर</strong> तक हो सकती हैं।</p><p>नीचे की पट्टी में <strong>Layer</strong> टैप करें।</p><p><img src="'+r+'" alt="लेयर"></p><ul><li>सूची में <strong>सबसे ऊपर</strong> वाली लेयर सबसे ऊपर दिखती है।</li><li>किसी लेयर पर ड्रॉ करने के लिए उस पर <strong>टैप</strong> करें। चुनी हुई लेयर के नाम पर टैप करके नाम बदलें।</li><li><strong>≡ हैंडल</strong> — क्रम बदलने के लिए खींचें (या पंक्ति पर लॉन्ग-प्रेस करके खींचें)।</li><li><strong>👁 आँख</strong> — लेयर छिपाएँ या दिखाएँ।</li><li><strong>गुलाबी +</strong> — नई लेयर जोड़ें।</li><li><strong>›</strong> — लेयर की सेटिंग।</li></ul><p>किसी लेयर को <strong>बाईं ओर स्वाइप करें</strong> — <strong>Lock</strong> (उस पर ड्रॉइंग रोकता है), <strong>Merge</strong> (नीचे वाली लेयर में मिलाता है), <strong>Duplicate</strong> और <strong>Delete</strong>।</p><p><img src="'+o+'" alt="लेयर के काम"></p><h2 id="लेयर-सेटिंग" tabindex="-1">लेयर सेटिंग <a class="header-anchor" href="#लेयर-सेटिंग" aria-label="Permalink to &quot;लेयर सेटिंग&quot;">​</a></h2><p><img src="'+s+'" alt="लेयर सेटिंग"></p><ul><li><p><strong>Name</strong> और <strong>Opacity</strong>।</p></li><li><p><strong>Blending mode</strong> — लेयर नीचे वाली लेयरों के साथ कैसे मिले: Normal, Multiply (परछाईं के लिए बढ़िया), Screen (रोशनी), Overlay, Darken, Lighten, Add, Color Dodge, Color Burn, Hard Light, Soft Light, Difference, Exclusion, Hue, Saturation, Color और Luminosity।</p><p><img src="'+n+'" alt="ब्लेंडिंग मोड"></p></li><li><p><strong>Alpha lock</strong> — सिर्फ़ उसी पर रंग लगे जो इस लेयर पर पहले से बना है। लकीरों के अंदर शेडिंग के लिए सही।</p></li><li><p><strong>Clipping mask</strong> — यह लेयर सिर्फ़ वहीं दिखे जहाँ नीचे वाली लेयर पर ड्रॉइंग है। कैरेक्टर के ऊपर पैटर्न या परछाईं वाली लेयर रखकर उसे क्लिप करें।</p></li><li><p><strong>Pixel effect</strong> — लेयर को बड़े-बड़े पिक्सेल में बदलता है (पिक्सेल का साइज़ चुनें)।</p></li><li><p><strong>Glow</strong> — ड्रॉइंग के चारों ओर मुलायम चमक, अपने रंग, साइज़ और तेज़ी के साथ।</p></li><li><p><strong>Merge down</strong> — इस लेयर को नीचे वाली में मिला देता है। <strong>Undo</strong> से दोनों वापस आ जाती हैं। <strong>Duplicate</strong> और <strong>Delete</strong> भी यहीं हैं।</p></li></ul><p>लेयर डिलीट करने पर वह <strong>हर</strong> फ़्रेम से हट जाती है।</p>',11)])])}const D=i(g,[["render",p]]);export{y as __pageData,D as default};
